// Open Graph image URL per route. Kept small (no page data imports) so the app shell can use it.
import { contentIndexByPath } from './contentIndex.js';

const BASE_URL = 'https://www.brandscalinghacks.com';
export const DEFAULT_OG_IMAGE = `${BASE_URL}/og/default.png`;

// Per-route Open Graph images (1200x630, generated by scripts/generate-og-images.cjs)
export const OG_IMAGES = {
  '/': `${BASE_URL}/og/home.png`,
  '/meta-ads-agency': `${BASE_URL}/og/meta-ads-agency.png`,
  '/tiktok-ads-agency': `${BASE_URL}/og/tiktok-ads-agency.png`,
  '/services': `${BASE_URL}/og/services.png`,
  '/contact': `${BASE_URL}/og/contact.png`,
  '/book': `${BASE_URL}/og/book.png`,
  '/growth': `${BASE_URL}/og/growth.png`,
  '/shopify-agency': `${BASE_URL}/og/shopify-agency.png`,
  '/viral-creatives': `${BASE_URL}/og/viral-creatives.png`,
  '/case-studies': `${BASE_URL}/og/case-studies.png`,
  '/roas-calculator': `${BASE_URL}/og/roas-calculator.png`,
  '/about': `${BASE_URL}/og/about.png`,
  '/blog': `${BASE_URL}/og/blog.png`
};

// Content pages (services, industries, tools, glossary...) get a card per URL in public/og/p/
export const contentOgFile = (path) => path.slice(1).replace(/\//g, '--');

export const ogImageFor = (path) => {
  if (OG_IMAGES[path]) return OG_IMAGES[path];
  if (path && contentIndexByPath(path)) return `${BASE_URL}/og/p/${contentOgFile(path)}.png`;
  if (path && path.startsWith('/blog/')) return `${BASE_URL}/og/blog/${path.slice(6)}-16x9.png`;
  return DEFAULT_OG_IMAGE;
};

